-- Generated from the supplied CSV. Historical campus listings are stored separately from verified offerings.
BEGIN;
ALTER TABLE public.academic_campuses ADD COLUMN IF NOT EXISTS state varchar(80);
ALTER TABLE public.academic_units ADD COLUMN IF NOT EXISTS display_name varchar(150);
ALTER TABLE public.academic_programmes ADD COLUMN IF NOT EXISTS display_name varchar(150);
ALTER TABLE public.academic_programmes ADD COLUMN IF NOT EXISTS name_ms varchar(150);
ALTER TABLE public.academic_programmes ADD COLUMN IF NOT EXISTS upu_code varchar(30);
ALTER TABLE public.academic_programmes ADD COLUMN IF NOT EXISTS catalogue_status varchar(50);
ALTER TABLE public.students ADD COLUMN IF NOT EXISTS study_level varchar(12) CHECK (study_level IN ('diploma','degree'));
ALTER TABLE public.student_registration_requests ADD COLUMN IF NOT EXISTS study_level varchar(12) CHECK (study_level IN ('diploma','degree'));
CREATE TABLE IF NOT EXISTS public.academic_campus_aliases (campus_name varchar(100) NOT NULL REFERENCES public.academic_campuses(name), alias varchar(100) NOT NULL, source_url text NOT NULL, PRIMARY KEY(campus_name,alias));
CREATE TABLE IF NOT EXISTS public.academic_programme_aliases (programme_code varchar(12) NOT NULL REFERENCES public.academic_programmes(code), alias varchar(150) NOT NULL, source_url text NOT NULL, PRIMARY KEY(programme_code,alias));
CREATE TABLE IF NOT EXISTS public.academic_historical_offerings (campus_name varchar(100) NOT NULL REFERENCES public.academic_campuses(name), programme_code varchar(12) NOT NULL REFERENCES public.academic_programmes(code), source_url text NOT NULL, source_checked_date date, PRIMARY KEY(campus_name,programme_code));
CREATE INDEX IF NOT EXISTS idx_academic_historical_offerings_code ON public.academic_historical_offerings(programme_code);
ALTER TABLE public.academic_campus_aliases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.academic_programme_aliases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.academic_historical_offerings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.academic_campus_aliases,public.academic_programme_aliases,public.academic_historical_offerings FROM PUBLIC,anon,authenticated;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='internpilih_app') THEN GRANT SELECT ON public.academic_campus_aliases,public.academic_programme_aliases,public.academic_historical_offerings TO internpilih_app; END IF; IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='internpilih_backend') THEN GRANT SELECT ON public.academic_campus_aliases,public.academic_programme_aliases,public.academic_historical_offerings TO internpilih_backend; END IF; END $$;
